/* ─── DB helpers ───────────────────────────────────────── */
async function dbLoad() {
  const { data, error } = await sb.from("cards").select("*").order("at", { ascending: false });
  if (error) { console.error(error); return {}; }
  const map = {};
  (data||[]).forEach(r => {
    map[r.id] = {
      id: r.id, name: r.name, tag: r.tag||"", bio: r.bio||"", loc: r.loc||"",
      photo: r.photo||"", banner: r.banner||"",
      ci: r.ci||0, pi: r.pi||0,
      links: r.links||{}, order: r.order_ids||[], layout: r.layout||"list",
      cv: r.cv||"", cvName: r.cv_name||"",
      menuPhotos: r.menu_photos||[], category: r.category||"personal",
      pw: r.pw, at: r.at||0,
    };
  });
  return map;
}
async function dbInsert(p) {
  const { error } = await sb.from("cards").insert({
    id: p.id, name: p.name, tag: p.tag, bio: p.bio, loc: p.loc,
    photo: p.photo, banner: p.banner, ci: p.ci, pi: p.pi,
    links: p.links, order_ids: p.order, layout: p.layout,
    cv: p.cv, cv_name: p.cvName, menu_photos: p.menuPhotos,
    category: p.category, pw: p.pw, at: p.at,
  });
  if (error) { console.error(error); return false; }
  return true;
}
async function dbUpdate(p) {
  const { error } = await sb.from("cards").update({
    name: p.name, tag: p.tag, bio: p.bio, loc: p.loc,
    photo: p.photo, banner: p.banner, ci: p.ci, pi: p.pi,
    links: p.links, order_ids: p.order, layout: p.layout,
    cv: p.cv, cv_name: p.cvName, menu_photos: p.menuPhotos,
  }).eq("id", p.id);
  if (error) { console.error(error); return false; }
  return true;
}
async function dbDelete(id) {
  const { error } = await sb.from("cards").delete().eq("id", id);
  if (error) { console.error(error); return false; }
  return true;
}

