/* ─── Cover palette ────────────────────────────────────── */
const COVERS = ["#1a1612","#0d3b7a","#7a2e10","#145228","#6a0dad","#2d2b8a","#0f4a6b","#7a5c00","#1a3a2a","#5a1a2a"];
const PATS   = [
  {l:"بدون", v:null, s:null},
  {l:"نقاط", v:"radial-gradient(circle,rgba(255,255,255,.2) 1px,transparent 1px)", s:"16px 16px"},
  {l:"خطوط", v:"repeating-linear-gradient(45deg,rgba(255,255,255,.07) 0,rgba(255,255,255,.07) 1px,transparent 1px,transparent 10px)", s:null},
  {l:"شبكة", v:"linear-gradient(rgba(255,255,255,.09) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.09) 1px,transparent 1px)", s:"18px 18px"},
];

function coverSt(ci,pi,banner) {
  if (banner) return {backgroundImage:`url(${banner})`,backgroundSize:"cover",backgroundPosition:"center"};
  const c=COVERS[ci]||COVERS[0], p=PATS[pi]||PATS[0];
  if (!p.v) return {backgroundColor:c};
  return {backgroundColor:c, backgroundImage:p.v, backgroundSize:p.s||"auto"};
}

function saveVCard(p) {
  const lines=["BEGIN:VCARD","VERSION:3.0",`FN:${p.name}`,
    p.tag?`TITLE:${p.tag}`:"", p.loc?`ADR:;;${p.loc};;;;`:"",
    p.links?.phone?`TEL;TYPE=CELL:${p.links.phone}`:"",
    p.links?.whatsapp?`TEL;TYPE=WORK:${p.links.whatsapp}`:"",
    p.links?.email?`EMAIL:${p.links.email}`:"",
    p.bio?`NOTE:${p.bio}`:"","END:VCARD"
  ].filter(Boolean).join("\r\n");
  const a=document.createElement("a");
  a.href=URL.createObjectURL(new Blob([lines],{type:"text/vcard"}));
  a.download=`${p.name.replace(/\s+/g,"_")}.vcf`; a.click();
  URL.revokeObjectURL(a.href);
}


